insert into public.events (id,slug,title_ja,title_zh,category,summary,fees,conditions,status,verified_at,updated_at) values ('bushiroad-20th-2027','bushiroad-20th-live-2027','ブシロード20周年記念ライブ','武士道20周年纪念 Live','音乐和声优活动','2027年6月12日、13日于横滨 Arena 举办。2027年1月8日发售的纪念书附带最速先行抽选申込券，申请详情尚未公布。','门票价格、席种及手续费尚未公布。纪念书1,760日元是商品价格，不是门票价格。','["需要纪念书附带的最速先行抽选申込券；申请方法与起止时间后日公开。","出演者各自演出日程后日公开，不能假定两天阵容相同。","已公布阵容包含 Ave Mujica、Morfonica、Poppin’Party、RAISE A SUILEN、Roselia、少女☆歌劇 レヴュースタァライト、蓮ノ空女学院スクールアイドルクラブ、ミルキィホームズ、夢限大みゅーたいぷ；后续以官网为准。"]','published','2026-10-28T00:00:00+09:00','2026-10-28T00:00:00+09:00') on conflict do nothing;
