insert into public.events (id,slug,title_ja,title_zh,category,summary,fees,conditions,status,verified_at,updated_at,image) values ('starlight-9th-fair-2026','starlight-9th-fair-2026','少女☆歌劇 レヴュースタァライト 9周年記念フェア ～L’Étoile innocente～','少女☆歌剧9周年纪念主题商品活动','其他联动','Animate指定店和Gamers举办9周年商品活动；这里收录已核实地址的8家参与分店。秋叶原另有纪念展示，详细展区楼层请核对官网。',null,'["商品、赠品与名额可能用尽，请查官方最新公告。","相关商品单次结账每满2,200日元获赠随机特典1张，赠完即止。","各品牌特典不同，通販和海外配布条件可能不同。"]','published','2026-10-28T09:00:00+09:00','2026-10-28T09:00:00+09:00','{"url":"https://bushiroad-creative.com/wordpress/wp-content/uploads/2026/08/25135814/Animate_RSL_9th_banner1920%C3%971080-1024x576.jpg","alt":"少女☆歌劇 レヴュースタァライト 9周年記念フェア ～L’Étoile innocente～ · 官方活动图","source_url":"https://bushiroad-creative.com/topics/104208/","checked_on":"2026-10-28"}') on conflict do nothing;
