insert into public.events (id,slug,title_ja,title_zh,category,summary,image,gallery,benefits,translated_rules,fees,conditions,status,verified_at,updated_at) values ('auto-16ad5931165da640','ras-tour2027','RAISE A SUILEN LIVE TOUR 2027','RAISE A SUILEN 2027 巡回演唱会','音乐和声优活动','RAISE A SUILEN 2027 巡回演唱会，共 5 站。举办日期、会场及最速先行抽选所需附券商品已公布；票务详情和报名受理期间仍待官方后续公布。','{"url":"https://bang-dream.com/wordpress/wp-content/uploads/2026/10/01101412/792592a1-3953d6b8-282c8cdc-873ba4a7.png","alt":"RAISE A SUILEN 2027 巡回演唱会","source_url":"https://bang-dream.com/events/ras-tour2027/","checked_on":"2026-10-29"}','[{"url":"https://bang-dream.com/wordpress/wp-content/uploads/2026/10/01101412/792592a1-3953d6b8-282c8cdc-873ba4a7.png","alt":"RAISE A SUILEN LIVE TOUR 2027","source_url":"https://bang-dream.com/events/ras-tour2027/","checked_on":"2026-10-29"}]','[]','[{"title":"最速先行抽选资格","text_zh":"凭 RAISE A SUILEN 16th Single「I AM WHO I AM」 初回生产分内附的申请券参加最速先行抽选。购买商品不等于获得门票。","evidence_ja":"※ RAISE A SUILEN 16th Single「I AM WHO I AM」 初回生産分に封入の申込券でご応募いただけます。","id":"auto-16ad5931165da640-rule-0","kind":"参加","source_url":"https://bang-dream.com/events/ras-tour2027/","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"报名期间与票务详情","text_zh":"官方将另行公布票务详情和受理期间。当前不能据此判断报名已开放。","evidence_ja":"※チケットの詳細や受付期間は後日公開いたします。","id":"auto-16ad5931165da640-rule-1","kind":"参加","source_url":"https://bang-dream.com/events/ras-tour2027/","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"现场注意事项","text_zh":"请在参加前阅读并遵守 Bushiroad Music 主办演出的注意事项；本场其他注意事项后续公布。","evidence_ja":"※その他の注意事項は後日公開いたします。","id":"auto-16ad5931165da640-rule-2","kind":"参加","source_url":"https://bang-dream.com/events/ras-tour2027/","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"}]',null,'["中文内容由机器辅助整理，请结合官方原文确认；时间均为日本时间。","凭 RAISE A SUILEN 16th Single「I AM WHO I AM」 初回生产分内附申请券报名。票务详情、开始及截止时间尚未公布。"]','published','2026-10-29T14:02:14.341Z','2026-10-29T14:02:14.341Z') on conflict do nothing;
