insert into public.events (id,slug,title_ja,title_zh,category,summary,image,gallery,benefits,translated_rules,fees,conditions,status,verified_at,updated_at) values ('auto-a0d13aed98742dfb','official-a0d13aed98742dfb','millsage LIVE 001「極夜」','millsage 首场演唱会「极夜」','音乐和声优活动','2026年12月25日在东京 Spotify O-WEST 举办，预计18:00入场、19:00开演，全站席6,600日元（含税）。最速先行需要单曲「鳴らす」首批附券，每人最多2张；严禁携带和使用发光应援物。','{"url":"https://bang-dream.com/wordpress/wp-content/uploads/2026/11/11192055/cfca7c86-fcbbe235-5d1d197d-e59be363.jpg","alt":"millsage 首场演唱会「极夜」","source_url":"https://bang-dream.com/events/millsage_1st/","checked_on":"2026-10-29"}','[{"url":"https://bang-dream.com/wordpress/wp-content/uploads/2026/11/11192055/cfca7c86-fcbbe235-5d1d197d-e59be363.jpg","alt":"millsage LIVE 001「極夜」","source_url":"https://bang-dream.com/events/millsage_1st/","checked_on":"2026-10-29"}]','[]','[{"title":"抽选资格与期限","text_zh":"2026年9月30日10:00至11月8日23:59受理。使用首张单曲「鳴らす」首批生产版附券，每人最多2张。","evidence_ja":"最速先行抽選\n受付期間：2026年9月30日(水) 10:00 ～ 11月8日(日) 23:59まで\n受付はこちら\n※ millsage 1st Single「鳴らす」 初回生産分に封入の申込券でご応募いただけます。\n※お一人様につき2枚までお申込みいただけます。","id":"auto-a0d13aed98742dfb-rule-0","kind":"参加","source_url":"https://bang-dream.com/events/millsage_1st/","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"应援物限制","text_zh":"禁止携带及使用所有发光应援物，包括荧光棒、应援灯、手环灯与戒指灯。","evidence_ja":"本公演では光り物の応援アイテム(サイリウム、ペンライト、バングルライト、リングライト、その他電飾やそれを伴うもの等)の持ち込み、使用を禁止とさせていただきます。","id":"auto-a0d13aed98742dfb-rule-1","kind":"参加","source_url":"https://bang-dream.com/events/millsage_1st/","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"}]',null,'["中文内容由机器辅助整理，请结合官方原文确认；时间均为日本时间。","需首张单曲「鳴らす」首批附券，每人最多2张；全站席，禁止发光应援物。"]','published','2026-10-29T14:02:14.341Z','2026-10-29T14:02:14.341Z') on conflict do nothing;
