insert into public.events (id,slug,title_ja,title_zh,category,summary,image,gallery,benefits,translated_rules,fees,conditions,status,verified_at,updated_at) values ('auto-9cfb2d214ec41aea','official-9cfb2d214ec41aea','Guilty Kiss Musical Performance 漆黒のWanted Ghost','Guilty Kiss 音乐剧《漆黑的 Wanted Ghost》','音乐和声优活动','2026年11月22、23日在沼津市民文化中心各演两场。这是3DCG音乐剧，声优本人不登台。现场普通指定席9,800日元，SPWN一般先到先得售票至11月12日23:59（日本时间），售完可提前结束；附周边票已截止。不能以配信票入场。','{"url":"https://www.lovelive-anime.jp/uranohoshi/live/image.php?img_path=/lovelive/jp/live/2026/04/18/1002/c56700lQDN6V4XEY/N7odUamdfI4wq7eg.jpeg","alt":"Guilty Kiss 音乐剧《漆黑的 Wanted Ghost》","source_url":"https://www.lovelive-anime.jp/uranohoshi/live/live_detail.php?p=Wanted_Ghost","checked_on":"2026-10-29"}','[{"url":"https://www.lovelive-anime.jp/uranohoshi/live/image.php?img_path=/lovelive/jp/live/2026/04/18/1002/c56700lQDN6V4XEY/N7odUamdfI4wq7eg.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/uranohoshi/live/live_detail.php?p=Wanted_Ghost","checked_on":"2026-10-29"},{"url":"https://www.lovelive-anime.jp/uranohoshi/live/image.php?img_path=/lovelive/jp/live/2026/05/20/1002/QMMA8Zbzz8dI3IMM/btyKdHSgCC5BgRAY.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/uranohoshi/live/live_detail.php?p=Wanted_Ghost","checked_on":"2026-10-29"},{"url":"https://www.lovelive-anime.jp/uranohoshi/live/image.php?img_path=/lovelive/jp/live/2026/05/20/1002/1de9UPokGkOFsZj4/vFhEwZH6jAJkyFM0.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/uranohoshi/live/live_detail.php?p=Wanted_Ghost","checked_on":"2026-10-29"},{"url":"https://www.lovelive-anime.jp/uranohoshi/live/image.php?img_path=/lovelive/jp/live/2026/05/20/1002/aJRdgGrgliwMu95K/gZqHMY4CX1ho0pGM.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/uranohoshi/live/live_detail.php?p=Wanted_Ghost","checked_on":"2026-10-29"},{"url":"https://www.lovelive-anime.jp/uranohoshi/live/image.php?img_path=/lovelive/