insert into public.events (id,slug,title_ja,title_zh,category,summary,image,gallery,benefits,translated_rules,fees,conditions,status,verified_at,updated_at) values ('auto-1c624082c33b649c','official-1c624082c33b649c','ラブライブ！サンシャイン!! 第５回沼津地元愛まつり','Aqours 第五届沼津地元爱祭','其他联动','2027年3月20–22日在沼津キラメッセぬまづ举办，每日昼夜两场、出演成员不同。最新一轮官方先行抽选已于2026年10月25日23:59（日本时间）截止，10月31日公布结果。同期地元爱物产展另设会场，细节尚待公布。','{"url":"https://www.lovelive-anime.jp/uranohoshi/live/image.php?img_path=/lovelive/jp/live/2026/06/30/1002/g4jfzkV9elMRjdWG/xMliz5BPocxHQzNT.jpeg","alt":"Aqours 第五届沼津地元爱祭","source_url":"https://www.lovelive-anime.jp/uranohoshi/live/live_detail.php?p=jimoai5th","checked_on":"2026-10-29"}','[{"url":"https://www.lovelive-anime.jp/uranohoshi/live/image.php?img_path=/lovelive/jp/live/2026/06/30/1002/g4jfzkV9elMRjdWG/xMliz5BPocxHQzNT.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/uranohoshi/live/live_detail.php?p=jimoai5th","checked_on":"2026-10-29"},{"url":"https://www.lovelive-anime.jp/uranohoshi/live/image.php?img_path=/lovelive/jp/live/2026/07/24/1002/IIwiPe4JtKjKxyID/UExbot6o7UkXnczZ.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/uranohoshi/live/live_detail.php?p=jimoai5th","checked_on":"2026-10-29"},{"url":"https://www.lovelive-anime.jp/uranohoshi/live/image.php?img_path=/lovelive/jp/live/2026/07/24/1002/roua832LtTWFqgRW/v89pV4rUdTPdYMwF.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/uranohoshi/live/live_detail.php?p=jimoai5th","checked_on":"2026-10-29"},{"url":"https://www.lovelive-anime.jp/uranohoshi/live/image.php?img_path=/lovelive/jp/live/2026/07/24/1002/6AZoV3zwMRijcepL/8h7QelWnAdjXRtNr.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/uranohoshi/live/live_detail.php?p=jimoai5th","checked_on":"2026-10-29"}]','[]','[{"title":"三天六场","text_zh":"每天昼场13:00入场、14:00开演；夜场17:30入场、18:30开演。3月20日伊波杏树、小宫有纱、降幡爱；21日逢田梨香子、高槻加奈子、铃木爱奈；22日诹访七香、齐藤朱夏、小林爱香。","evidence_ja":"開催概要・出演者\n＜Day.1＞\n2027年3月20日（土）\n＜昼公演＞13:00開場／14:00開演\n＜夜公演＞17:30開場／18:30開演\n【出演】伊波杏樹（高海千歌役）、小宮有紗（黒澤ダイヤ役）、降幡 愛（黒澤ルビィ役）\n＜Day.2＞\n2027年3月21日（日）\n＜昼公演＞13:00開場／14:00開演\n＜夜公演＞17:30開場／18:30開演\n【出演】逢田梨香子（桜内梨子役）、高槻かなこ（国木田花丸役）、鈴木愛奈（小原鞠莉役）\n＜Day.3＞\n2027年3月22日（月・祝）\n＜昼公演＞13:00開場／14:00開演\n＜夜公演＞17:30開場／18:30開演\n【出演】諏訪ななか（松浦果南役）、斉藤朱夏（渡辺 曜役）、小林愛香（津島善子役）\n会場\nキラメッセぬまづ（静岡県沼津市大手1丁目1−4）","id":"auto-1c624082c33b649c-rule-0","kind":"参加","source_url":"https://www.lovelive-anime.jp/uranohoshi/live/live_detail.php?p=jimoai5th","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"票种与视线限制","text_zh":"指定席及注释指定席均为普通8,500日元、附周边11,500日元（含税）。注释席可能看不清或看不到部分出演者、演出及舞台。","evidence_ja":"チケット\n全席指定（グッズ付き）：11,500円（税込）\n全席指定：8,500円（税込）\n・2026/9/25追記\n注釈付き指定席（グッズ付き）：11,500円（税込）\n注釈付き指定席：8,500円（税込）\n※注釈付き指定席は出演者、演出及びステージの一部が見えにくい、または一部が見えないお席となります。","id":"auto-1c624082c33b649c-rule-1","kind":"参加","source_url":"https://www.lovelive-anime.jp/uranohoshi/live/live_detail.php?p=jimoai5th","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"附周边票须下载兑换券","text_zh":"特典为按演出日设计的B6亚克力板，含复制签名与序列号；当天现场领取，未领取作废，不邮寄，瑕疵仅当天更换。申请者和同行者均需能安装eplus App的手机，事前分配独立周边兑换券，否则同行者不能领取。","evidence_ja":"＜グッズ付きチケットについて＞\n箔押しメンバー複製サイン＆シリアルナンバー入り B6アクリルプレート (公演日別デザイン)\n※グッズは公演当日に会場でのお渡しを予定しております。\n当日の受け渡しに関する詳細は後日ご案内いたします。\n※公演当日にお受け取りができない場合は無効となります。\n事前・事後の発送は行いませんので、あらかじめご了承ください。\n※不良品の交換は当日のみ対応いたします。\n※グッズ付きチケットをご購入の方は、別途「グッズ引換券」（スマチケ）のダウンロードが必要となります。「グッズ引換券」のダウンロードにはイープラスアプリ（無料）のインストールが必要です。\n※複数枚お申込みの場合、事前に必ず同行者様へ「グッズ引換券」の分配をおこなってください。\n「グッズ引換券」を分配していない場合、同行者様はグッズのお受け取りができません。\n※同行者の方もイープラスアプリ（無料）をインストールできるスマートフォンが必要です。（申込者の方と同様の動作機種・推奨環境が必要です）\n※チケットご購入時の手数料に、グッズ引換にかかる手数料も含まれます。","id":"auto-1c624082c33b649c-rule-2","kind":"参加","source_url":"https://www.lovelive-anime.jp/uranohoshi/live/live_detail.php?p=jimoai5th","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"最新抽选已截止","text_zh":"官方先行9月26日18:00至10月25日23:59受理；10月31日13:00起公布结果，付款至11月3日21:00。每人每场最多4张，可报多场，四种票均在本轮销售。均为日本时间，旧页眉“受理中”不能替代日期判断。","evidence_ja":"＜オフィシャル先行（抽選）＞★どなたでもお申し込みいただけます！★\n本受付では、全席指定（グッズ付き／グッズなし）と注釈付き指定席（グッズ付き／グッズなし）の4券種を販売いたします。\n■受付URL： https://eplus.jp/jimoai2027/\n■受付期間：2026年9月26日（土）18:00～10月25日（日）23:59\n■当落発表：2026年10月31日（土）13:00～\n■入金期間：2026年10月31日（土）13:00～11月3日（火・祝）21:00\n※枚数制限：お一人様、1公演につき4枚までお申込み可能（複数公演申込可）","id":"auto-1c624082c33b649c-rule-3","kind":"参加","source_url":"https://www.lovelive-anime.jp/uranohoshi/live/live_detail.php?p=jimoai5th","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"身份与取消","text_zh":"3岁以上收费，需免费eplus会员，另收手续费；仅受理期内可改退申请，中选后不能取消购买。所有入场者包括同行者须登记人脸照片，并携带照片证件。","evidence_ja":"●注意事項●\n※3歳以上有料\n※お申込み時にイープラスの会員登録（無料）が必要です。\n※必ず受付画面にて、注意事項をご確認の上、お申込みください。\n※抽選販売分は先着順での受付ではございませんので、受付期間内にお申込みください。当落および座席などは、期間内にお申込みいただいた中から抽選で決定いたします。\n※お席に関してのお問合せには、お答えできません。\n※お申込み内容の変更・取消しは受付期間中のみおこなえます。当選後の変更・取消し(購入辞退)は一切お受けできませんのでご注意ください。\n※チケット代金の他に各種手数料が必要となります。\n※アルコール類の持込、及び飲酒してのご入場は固くお断りいたします。\n※開場・開演時間、出演者は諸事情により変更になる場合がございます。それに伴うチケット代・交通費等の払い戻しはいたしません。あらかじめご了承ください。\n※ご来場のお客様におかれましては、公演における注意事項を必ずお読みいただき、遵守くださいますようお願いいたします。ご協力いただけない場合、ご入場いただけない可能性もございますので、あらかじめご了承ください。\n※顔認証入場システムを利用したチケット販売のため、顔写真登録が必要となります。必ず来場者ご本人様がお申込みください。（チケットを複数枚購入される場合、同行者の顔写真登録も必要となります。）\n※顔認証入場システムでご本人と判断できない場合、顔写真付きの公的身分証でご本人確認をさせていただきますので、必ずご持参ください。","id":"auto-1c624082c33b649c-rule-4","kind":"参加","source_url":"https://www.lovelive-anime.jp/uranohoshi/live/live_detail.php?p=jimoai5th","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"同期物产展","text_zh":"沼津地元爱物产展在Plaza Verde Convention Hall A，地点不同于演出主会场；具体开放时间和参加方式尚待更新。","evidence_ja":"同時開催\n沼津地元愛物産展\nプラサヴェルデ コンベンションホールA（〒410-0801 静岡県沼津市大手町1-1-4）\n（詳細は近日更新予定！）\nhttps://www.plazaverde.jp/jimoai-event/","id":"auto-1c624082c33b649c-rule-5","kind":"参加","source_url":"https://www.lovelive-anime.jp/uranohoshi/live/live_detail.php?p=jimoai5th","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"}]',null,'["中文内容由机器辅助整理，请结合官方原文确认；时间均为日本时间。","本轮已截止。官方写明任何人都可报名，无商品附券前提；每人每场最多4张。每天昼夜两场。"]','published','2026-10-29T14:02:14.341Z','2026-10-29T14:02:14.341Z') on conflict do nothing;
