insert into public.events (id,slug,title_ja,title_zh,category,summary,image,gallery,benefits,translated_rules,fees,conditions,status,verified_at,updated_at) values ('auto-69db4e82e137a6d8','official-69db4e82e137a6d8','ラブライブ！蓮ノ空女学院スクールアイドルクラブ Link Live Dream ～106期新入生入部記念公演～｜LIVE＆EVENT','莲之空 Link Live Dream「106期新生入部纪念公演」','音乐和声优活动','2027年1月22日在东京日本武道馆举办，16:00入场、17:00开演。最速先行抽选于2026年9月25日12:00至11月8日23:59（日本时间）受理，每人每场最多2张。','{"url":"https://www.lovelive-anime.jp/hasunosora/live-event/image.php?img_path=/lovelive/jp/live/2026/07/10/1002/ArSfpIbjy7mEVKSZ/H6vKaImomtMo5XkA.jpeg","alt":"莲之空 Link Live Dream「106期新生入部纪念公演」","source_url":"https://www.lovelive-anime.jp/hasunosora/live-event/live_detail.php?p=LLDream106","checked_on":"2026-10-29"}','[{"url":"https://www.lovelive-anime.jp/hasunosora/live-event/image.php?img_path=/lovelive/jp/live/2026/07/10/1002/ArSfpIbjy7mEVKSZ/H6vKaImomtMo5XkA.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/hasunosora/live-event/live_detail.php?p=LLDream106","checked_on":"2026-10-29"}]','[]','[{"title":"票价与U-20","text_zh":"全席指定13,000日元，U-20为6,500日元（均含税）；U-20计划随一般销售开放，申请者及同行者须当天未满20岁并出示年龄证明，每人每场最多2张。","evidence_ja":"【チケット料金】\n全席指定：13,000円（税込）\nU-20割引チケット：6,500円（税込）\n----------\n＜U-20割引チケットについて＞\n本公演は、20歳未満の方にもご参加いただきやすくするため、対象の方に向け「U-20割引チケット」を販売いたします。\n・ 公演当日時点で20歳未満の方が購入できるチケットとなります。\n・一般発売に合わせ販売予定です。枚数には限りがございますので、あらかじめご了承ください。\n・当日はご入場にあたり、年齢を確認できる身分証明書を確認させていただきます。\n・U-20割引チケットはお一人様1公演につき2枚までお申込みいただけますが、同行者の方も公演当日時点で20歳未満の方に限ります。あらかじめご了承ください。\n----------","id":"auto-69db4e82e137a6d8-rule-0","kind":"参加","source_url":"https://www.lovelive-anime.jp/hasunosora/live-event/live_detail.php?p=LLDream106","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"抽选、结果及付款","text_zh":"最速先行并非先到先得：9月25日12:00至11月8日23:59受理，11月14日13:00起公布结果，付款期为11月14日13:00至17日21:00（日本时间），每人每场最多2张。","evidence_ja":"＜最速先行抽選＞\n----------\n■受付URL： https://eplus.jp/hasunosoralldream106/\n■受付期間：2026年9月25日（金）12:00～11月8日（日）23:59\n■当落発表：2026年11月14日（土）13:00～\n■入金期間：2026年11月14日（土）13:00～11月17日（火）21:00\n※枚数制限：お一人様1公演につき、各公演それぞれに2枚までお申込み可能（複数公演申込可能）\n----------","id":"auto-69db4e82e137a6d8-rule-1","kind":"参加","source_url":"https://www.lovelive-anime.jp/hasunosora/live-event/live_detail.php?p=LLDream106","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"注册和年龄","text_zh":"需免费注册eplus会员；3岁以上收费，不能据此认定3岁以下免费入场。","evidence_ja":"※3歳以上有料\n※お申込み時にイープラスの会員登録（無料）が必要です。","id":"auto-69db4e82e137a6d8-rule-2","kind":"参加","source_url":"https://www.lovelive-anime.jp/hasunosora/live-event/live_detail.php?p=LLDream106","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"修改与费用","text_zh":"只能在受理期间修改或取消申请；中选后不能取消购买。票价之外另有手续费。","evidence_ja":"※お申込み内容の変更・取消しは受付期間中のみおこなえます。当選後の変更・取消し(購入辞退)は一切お受けできませんのでご注意ください。\n※チケット代金の他に各種手数料が必要となります。","id":"auto-69db4e82e137a6d8-rule-3","kind":"参加","source_url":"https://www.lovelive-anime.jp/hasunosora/live-event/live_detail.php?p=LLDream106","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"实名入场","text_zh":"申请者和同行者均需登记人脸照片；随身携带带照片的官方身份证件，提前完成同行者登记。","evidence_ja":"※顔認証入場システムを利用したチケット販売のため、顔写真登録が必要となります。必ず来場者ご本人様がお申込みください。（チケットを複数枚購入される場合、同行者の顔写真登録も必要となります。）\n※顔認証入場システムでご本人と判断できない場合、顔写真付きの公的身分証でご本人確認をさせていただきますので、必ずご持参ください。\n▼顔認証入場システムのご利用について\nhttps://eplus.jp/faceticket_about/\n■同行者登録とは？\nhttps://eplus.jp/sf/guide/fellow-ep/\n■【同行者登録】手続きはこちら\nhttps://member.eplus.jp/update-dokosha\n※受付開始前からお手続きいただけます。","id":"auto-69db4e82e137a6d8-rule-4","kind":"参加","source_url":"https://www.lovelive-anime.jp/hasunosora/live-event/live_detail.php?p=LLDream106","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"}]',null,'["中文内容由机器辅助整理，请结合官方原文确认；时间均为日本时间。","每人每场最多2张，需eplus会员及申请者、同行者人脸登记；日本时间11月8日23:59截止（北京时间22:59）。"]','published','2026-10-29T14:02:14.341Z','2026-10-29T14:02:14.341Z') on conflict do nothing;
