insert into public.events (id,slug,title_ja,title_zh,category,summary,image,gallery,benefits,translated_rules,fees,conditions,status,verified_at,updated_at) values ('auto-35517508cbd07a8f','official-35517508cbd07a8f','カクダイ製菓（愛知県名古屋市）が製造・販売する「クッピーラムネ」と「ラブライブ！シリーズ」のコラボレーション決定！！','Love Live! × クッピーラムネ 名古屋 PremiumShop 联动','快闪店','为纪念Love Live! Fes在名古屋举行，系列与名古屋零食品牌クッピーラムネ合作推出新绘插画。线下销售点于2026年11月13日至16日在AEON MALL名古屋Dome前2楼美食广场旁连桥营业，10:00–21:00。具体商品、价格和入场安排待后续公布；这不是演唱会场次。','{"url":"https://www.lovelive-anime.jp/nijigasaki/module/image.php?img_path=/lovelive/jp/news/2026/10/28/1002/S9j3ef0Xv5bIH8WK/oyBor1Vdj8JIbCrK.jpeg","alt":"Love Live! × クッピーラムネ 名古屋 PremiumShop 联动","source_url":"https://www.lovelive-anime.jp/nijigasaki/detail.php?p=01_6729","checked_on":"2026-10-29"}','[{"url":"https://www.lovelive-anime.jp/nijigasaki/module/image.php?img_path=/lovelive/jp/news/2026/10/28/1002/S9j3ef0Xv5bIH8WK/oyBor1Vdj8JIbCrK.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/nijigasaki/detail.php?p=01_6729","checked_on":"2026-10-29"},{"url":"https://www.lovelive-anime.jp/nijigasaki/module/image.php?img_path=/lovelive/jp/news/2026/10/27/1002/pNJxcCi9f6z5GmSd/Elg0lrIDL6sICAfH.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/nijigasaki/detail.php?p=01_6729","checked_on":"2026-10-29"}]','[]','[{"title":"销售点与营业时间","text_zh":"地点为AEON MALL名古屋Dome前2楼美食广场旁连桥；11月13日至16日，10:00–21:00。","evidence_ja":"イオンモールナゴヤドーム前 2階フードコート横ブリッジ\nイオンモールナゴヤドーム前 HP： https://www.aeon.jp/sc/nagoyadomemae/\n開催期間：2026年11月13日(金)～11月16日(月)\n営業時間：10:00～21:00","id":"auto-35517508cbd07a8f-rule-0","kind":"参加","source_url":"https://www.lovelive-anime.jp/nijigasaki/detail.php?p=01_6729","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"后续信息","text_zh":"商品细节尚待后续公告，库存与销售情况以PremiumShop官方更新为准。","evidence_ja":"詳細は続報をお待ちください♪","id":"auto-35517508cbd07a8f-rule-1","kind":"参加","source_url":"https://www.lovelive-anime.jp/nijigasaki/detail.php?p=01_6729","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"}]',null,'["中文内容由机器辅助整理，请结合官方原文确认；时间均为日本时间。","仅确认线下销售点、日期与10:00–21:00营业时间；商品、价格及入场安排待续报，不代表无需预约或库存可用。"]','published','2026-10-29T14:02:14.341Z','2026-10-29T14:02:14.341Z') on conflict do nothing;
