insert into public.events (id,slug,title_ja,title_zh,category,summary,image,gallery,benefits,translated_rules,fees,conditions,status,verified_at,updated_at) values ('auto-859eb48cedf3ebad','official-859eb48cedf3ebad','ラブライブ！蓮ノ空女学院スクールアイドルクラブ × #カラオケの鉄人 コラボ詳細情報解禁のお知らせ！','莲之空 × 卡拉OK铁人「Dreamy Parlor!」','联动咖啡厅','2026年10月29日至12月13日在全国11家店举办，覆盖东京、福冈、大阪、名古屋、松山、京都、新潟、札幌。6家店设主题房，每人每2小时2,200日元；周边满2,000日元赠随机明信片，饮品赠杯垫。','{"url":"https://www.lovelive-anime.jp/hasunosora/shared/api/image.php?img_path=/lovelive/jp/news/2026/10/16/1002/HM1gMtfUDnbnGsNY/wugzjbX7TttJPyph.jpeg","alt":"莲之空 × 卡拉OK铁人「Dreamy Parlor!」","source_url":"https://www.lovelive-anime.jp/hasunosora/news/detail.php?p=01_6708","checked_on":"2026-10-29"}','[{"url":"https://www.lovelive-anime.jp/hasunosora/shared/api/image.php?img_path=/lovelive/jp/news/2026/10/16/1002/HM1gMtfUDnbnGsNY/wugzjbX7TttJPyph.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/hasunosora/news/detail.php?p=01_6708","checked_on":"2026-10-29"},{"url":"https://www.lovelive-anime.jp/hasunosora/shared/api/image.php?img_path=/lovelive/jp/news/2026/10/16/1002/q9jHkUNWZGhu668t/eWuOUTeMJFkIHUIE.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/hasunosora/news/detail.php?p=01_6708","checked_on":"2026-10-29"},{"url":"https://www.lovelive-anime.jp/hasunosora/shared/api/image.php?img_path=/lovelive/jp/news/2026/10/16/1002/TuPN28FWpTkw6ABh/FpcAww2ek7LumvzN.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/hasunosora/news/detail.php?p=01_6708","checked_on":"2026-10-29"},{"url":"https://www.lovelive-anime.jp/hasunosora/shared/api/image.php?img_path=/lovelive/jp/news/2026/10/16/1002/cwpn8vreGx2DxGGq/wDKq2zotqYDydpra.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/hasunosora/news/detail.php?p=01_6708","checked_on":"2026-10-29"},{"url":"https://www.lovelive-anime.jp/hasunosora/shared/api/image.php?img_path=/lovelive/jp/news/2026/10/16/1002/EM1g9bwdX9rWInV4/QnHEOpjiwG0CPHVL.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/hasunosora/news/detail.php?p=01_6708","checked_on":"2026-10-29"},{"url":"https://www.lovelive-anime.jp/hasunosora/shared/api/image.php?img_path=/lovelive/jp/news/2026/10/16/1002/NDIF3BD8Hmv23dmB/YQrOzsRMnV77lRY7.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/hasunosora/news/detail.php?p=01_6708","checked_on":"2026-10-29"}]','[]','[{"title":"活动期间及11店","text_zh":"10月29日至12月13日；东京4店及福冈天神、大阪难波、名古屋名站、松山银天街、京都河原町、新潟万代City、札幌薄野。并非每家都有主题房。","evidence_ja":"【開催期間】\n2026年10月29日(木)～2026年12月13日(日)\n【開催場所】\nカラオケの鉄人 全国11店舗\n新宿大ガード店、池袋東口店、渋谷道玄坂店、秋葉原電気街店、福岡天神店、大阪なんば店、名古屋名駅店、松山銀天街店、京都河原町店、新潟万代シティ店、札幌すすきの店\n※コンセプトルームの展開有無は店舗によって異なります。","id":"auto-859eb48cedf3ebad-rule-0","kind":"参加","source_url":"https://www.lovelive-anime.jp/hasunosora/news/detail.php?p=01_6708","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"周边赠品","text_zh":"周边购买金额达到2,000日元（含税）赠随机明信片1张，共9种；原文不是“每满2,000日元”。","evidence_ja":"【販売グッズ】\nコラボ店舗各店にて、ジャージメイドな描き下ろしイラストを使用したコラボグッズの販売をいたします！\nコラボグッズを¥2,000(税込)以上ご購入で特典ポストカード（全9種）をランダムで1枚プレゼントいたします。","id":"auto-859eb48cedf3ebad-rule-1","kind":"参加","source_url":"https://www.lovelive-anime.jp/hasunosora/news/detail.php?p=01_6708","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"饮品及挑战","text_zh":"指定歌曲挑战100分可获饮品特典全套，66/77/88/99分获1张。","evidence_ja":"【課題曲チャレンジ】\nコラボ店舗各店にて、課題曲チャレンジを開催！\n採点機能を入れて指定の楽曲を歌うと特典に応じた特典をゲットできます。\n100点達成でドリンク特典のコンプリートセットを、ゾロ目（66,77,88,99点）達成でドリンク特典を1枚プレゼントいたします！","id":"auto-859eb48cedf3ebad-rule-2","kind":"参加","source_url":"https://www.lovelive-anime.jp/hasunosora/news/detail.php?p=01_6708","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"主题房","text_zh":"10月19日18:00（日本时间）开始预约。新宿大Guard、涩谷道玄坂、秋叶原电气街、福冈天神、大阪难波、名古屋名站6店；每人每2小时2,200日元（含税）。","evidence_ja":"【コンセプトルーム】\n一部店舗では、描き下ろしイラストと一緒にカラオケを楽しめるコンセプトルームも展開いたします！\nコンセプトルームは10/19(月)18:00より予約開始！\n◼︎開催店舗\n新宿大ガード店、渋谷道玄坂店、秋葉原電気街店、福岡天神店、大阪なんば店、名古屋名駅店\n◼︎利用料金\nお一人様1枠（2時間）：¥2,200 (税込)","id":"auto-859eb48cedf3ebad-rule-3","kind":"参加","source_url":"https://www.lovelive-anime.jp/hasunosora/news/detail.php?p=01_6708","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"饮品特典","text_zh":"点联动饮品赠杯垫1张；另有附额外特典的套餐。","evidence_ja":"【コラボドリンク】\nコラボ店舗各店にてメンバーをイメージしたコラボドリンクの販売をいたします！\nコラボドリンクをご注文で特典コースターを1枚プレゼントいたします。\nまた、追加の特典がついたセットメニューもございます！","id":"auto-859eb48cedf3ebad-rule-4","kind":"参加","source_url":"https://www.lovelive-anime.jp/hasunosora/news/detail.php?p=01_6708","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"}]',null,'["中文内容由机器辅助整理，请结合官方原文确认；时间均为日本时间。","普通饮品、物贩与主题房条件不同，请按门店说明确认；不能据此认定无需预约。"]','published','2026-10-29T14:02:14.341Z','2026-10-29T14:02:14.341Z') on conflict do nothing;
